\set ON_ERROR_STOP 1
begin;
reset role;
create temp table cp(k text primary key,v uuid);
grant all on cp to authenticated,service_role;
insert into auth.users(email,email_confirmed_at,raw_user_meta_data) values
 ('career.one@example.com',now(),'{"candidate_portal":true}'),('career.two@example.com',now(),'{"candidate_portal":true}'),('career.unverified@example.com',null,'{"candidate_portal":true}');
set constraints all immediate;
insert into cp select 'one',id from auth.users where email='career.one@example.com';
insert into cp select 'two',id from auth.users where email='career.two@example.com';
insert into cp select 'unverified',id from auth.users where email='career.unverified@example.com';
select test.check(not exists(select 1 from profiles where id in(select v from cp)),'candidate signup creates no staff profiles or employee approval requests');
select test.check(not exists(select 1 from employee_welcome_emails where employee_id in(select v from cp)),'candidate signup queues no employee welcome email');
select test.login('hr_head');
select hr_career_posting(jsonb_build_object('position_id',(select id from hr_positions where title='Backend Developer'),'title','Portal Developer','description','Build reliable applications with our engineering team.','location','Mumbai','employment_type','FULL_TIME','published',true));
reset role;
insert into cp select 'job',id from career_postings where title='Portal Developer';
set role anon;
select test.check(career_jobs()->>'total'='1','public sees the published job');
select test.must_fail($$select * from career_applicants$$,'anonymous cannot read candidate data','permission denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='unverified'),'role','authenticated')::text,true);
set role authenticated;
-- registration needs no e-mail verification (migration 20261229000100): an unverified candidate-portal account works...
select test.check(career_profile()->>'name'='','a candidate whose e-mail was never verified can use the portal');
select test.check(jsonb_typeof(career_notifications())='array','...and read their own updates');
reset role;
select test.check((select count(*)=1 from career_applicants where id=(select v from cp where k='unverified')),'...and gets their own applicant record, linked to their account');
-- ...but an account that is not a candidate-portal account is still refused, verified or not
insert into auth.users(email,email_confirmed_at,raw_user_meta_data) values ('career.notcandidate@example.com',now(),'{}');
set constraints all immediate;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from auth.users where email='career.notcandidate@example.com'),'role','authenticated')::text,true);
set role authenticated;
select test.must_fail($$select career_profile()$$,'a non-candidate account is still refused','not registered for the candidate portal');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.check(career_profile()->>'name'='','empty candidate profile is real, not seeded');
select career_profile('{"name":"Portal Candidate","phone":"9847650321","city":"Mumbai","state":"Maharashtra","education":"Graduate","experience":"Fresher","skills":"TypeScript","bio":"","version":1}');
select test.must_fail($$select career_profile('{"name":"Conflict","phone":"9847650321","version":1}')$$,'stale edits cannot overwrite profile','CONFLICT');
insert into cp select 'file',(career_file(null,'{"file_name":"resume.pdf","size_bytes":10,"storage_provider":"SUPABASE"}')->>'id')::uuid;
select test.must_fail($$select career_file((select v from cp where k='file'),'{"action":"COMPLETE","size_bytes":10}')$$,'browser cannot attest upload content verification','FORBIDDEN');
select test.must_fail($$select career_apply((select v from cp where k='job'),(select v from cp where k='file'))$$,'unfinished resumes cannot be submitted','uploaded resume');
reset role;
set role service_role;
select career_file_verified((select v from cp where k='file'),10,(select v::text from cp where k='one')||'/sealed/test.pdf');
reset role;
set role authenticated;
insert into cp select 'app',(career_apply((select v from cp where k='job'),(select v from cp where k='file'))->>'id')::uuid;
select test.check((career_apply((select v from cp where k='job'),(select v from cp where k='file'))->>'id')::uuid=(select v from cp where k='app'),'duplicate submission returns the same application');
select career_profile('{"name":"New Profile Name","phone":"9847650321","city":"Pune","state":"Maharashtra","education":"Graduate","experience":"Fresher","skills":"TypeScript","bio":"","version":2}');
select test.check(career_applications()->0#>>'{snapshot,profile,name}'='Portal Candidate','submitted profile snapshot is immutable');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='two'),'role','authenticated')::text,true);
set role authenticated;
select test.check(jsonb_array_length(career_applications())=0,'another candidate cannot see the application');
select test.must_fail($$select career_file((select v from cp where k='file'))$$,'another candidate cannot read the resume','NOT_FOUND');
select test.must_fail($$select hr_career_posting()$$,'candidate cannot manage jobs','FORBIDDEN');
select test.must_fail($$select career_file_verified((select v from cp where k='file'),10,(select v::text from cp where k='one')||'/sealed/test.pdf')$$,'candidate cannot bypass upload verification','permission denied');
select test.login('tm_a');
select test.must_fail($$select career_profile()$$,'ordinary staff cannot enter candidate membership implicitly','not registered');
select test.must_fail($$select hr_career_posting()$$,'another department cannot manage recruitment jobs','FORBIDDEN');
reset role;
select test.check((select count(*)=1 from career_applications),'only one application exists');
select test.check(exists(select 1 from hr_candidates where email='career.one@example.com'),'application feeds existing HR recruitment');
select test.check(exists(select 1 from audit_logs where action='CANDIDATE_PROFILE_UPDATED' and metadata->>'actor_auth_id'=(select v::text from cp where k='one')),'candidate audit identifies the authenticated actor');
-- Assessment and progression checks share the isolated application fixture.
select test.login('hr_head');
set role authenticated;
insert into cp select 'test',(hr_career_tests('{"title":"Portal MCQ","duration_minutes":10,"pass_percent":100,"questions":[{"prompt":"Choose two","options":["one","two"],"correct":1}]}')->0->>'id')::uuid;
insert into cp select 'attempt',(hr_career_invite((select v from cp where k='app'),(select v from cp where k='test'),now()+interval '1 day')->>'id')::uuid;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='two'),'role','authenticated')::text,true);
set role authenticated;
select test.must_fail($$select career_assessment((select v from cp where k='attempt'),'{"action":"START"}')$$,'another candidate cannot start an attempt','NOT_FOUND');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.check(not (career_assessment((select v from cp where k='attempt'),'{"action":"START"}')::text like '%"correct"%'),'candidate never receives the answer key');
select test.must_fail($$select career_assessment((select v from cp where k='attempt'),'{"action":"SAVE","version":1,"answers":{"0":1}}')$$,'stale answer writes refused','CONFLICT');
select career_assessment((select v from cp where k='attempt'),jsonb_build_object('action','SAVE','version',(career_assessment((select v from cp where k='attempt'))->>'version')::integer,'answers','{"0":1}'::jsonb));
select test.check(career_assessment((select v from cp where k='attempt'))#>>'{answers,0}'='1','saved answer survives reopening');
select career_assessment((select v from cp where k='attempt'),jsonb_build_object('action','SUBMIT','version',(career_assessment((select v from cp where k='attempt'))->>'version')::integer,'answers','{"0":1}'::jsonb));
select test.check((career_assessment((select v from cp where k='attempt'))->>'passed')::boolean,'score is calculated server-side');
select test.check(career_assessment((select v from cp where k='attempt'),'{"action":"SUBMIT","version":1,"answers":{}}')->>'score'='1','submit retry cannot alter a finalized result');
reset role;
select test.check((select stage='ASSESSMENT' from career_applications where id=(select v from cp where k='app')),'passing does not select or activate the candidate');
select test.login('hr_head');
set role authenticated;
select test.must_fail($$select hr_career_stage((select v from cp where k='app'),'SELECTED',2,null)$$,'interview stages cannot be skipped','CONFLICT');
select hr_career_stage((select v from cp where k='app'),'INTERVIEW',2,'Your assessment passed. Interview details will follow.');
select test.must_fail($$select hr_career_stage((select v from cp where k='app'),'SELECTED',3,null)$$,'selection requires both interview outcomes','Complete the HR');
select hr_career_interview((select v from cp where k='app'),jsonb_build_object('round','HR','scheduled_at',now()-interval '1 hour','location','Office reception'));
select hr_career_interview((select v from cp where k='app'),jsonb_build_object('round','HR','scheduled_at',now()-interval '1 hour','location','Office reception'));
select test.check(jsonb_array_length(hr_career_applications()->'items'->0->'interviews')=1,'retrying an interview schedule creates no duplicate round or notification');
reset role;
select test.check(not exists(select 1 from profiles where id=(select v from cp where k='one')),'assessment success grants no staff profile');
-- HR decisions, unpublished offers, private documents and existing training integration.
select test.login('hr_head');
set role authenticated;
insert into cp select 'hr_interview',id from jsonb_to_recordset((hr_career_applications()->'items')->0->'interviews') as x(id uuid);
select hr_career_interview((select v from cp where k='app'),jsonb_build_object('id',(select v from cp where k='hr_interview'),'version',1,'status','COMPLETED','recommendation','PROCEED','internal_feedback','Internal panel feedback must remain private'));
insert into cp select 'dh_interview',(hr_career_interview((select v from cp where k='app'),jsonb_build_object('round','DEPARTMENT_HEAD','scheduled_at',now()-interval '1 hour','location','Department office'))->>'id')::uuid;
select hr_career_interview((select v from cp where k='app'),jsonb_build_object('id',(select v from cp where k='dh_interview'),'version',1,'status','COMPLETED','recommendation','PROCEED','internal_feedback','Internal department approval'));
select hr_career_stage((select v from cp where k='app'),'SELECTED',3,'Selected after panel review');
insert into cp select 'offer',(hr_career_offer((select v from cp where k='app'),jsonb_build_object('title','Portal employment offer','terms','Approved offer terms for the candidate integration test.','expires_at',now()+interval '7 days','joining_date',current_date))->>'id')::uuid;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.check(jsonb_array_length(career_offers())=0,'draft offer is invisible to candidate');
select test.check(career_interviews()::text not like '%Internal panel%','internal interview feedback is never returned to candidate');
select test.must_fail($$select career_offers((select v from cp where k='offer'),'{"response":"ACCEPTED","version":1}')$$,'candidate cannot accept an unpublished offer','NOT_FOUND');
select test.login('hr_head');
select hr_career_offer((select v from cp where k='app'),jsonb_build_object('id',(select v from cp where k='offer'),'version',1,'action','RELEASE'));
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.check(jsonb_array_length(career_offers())=1,'released offer is visible');
select career_offers((select v from cp where k='offer'),'{"response":"ACCEPTED","version":2}');
select career_offers((select v from cp where k='offer'),'{"response":"ACCEPTED","version":2}');
select test.check(career_applications()->0->>'stage'='JOINING','offer acceptance moves to joining, safely on retry');
select test.login('hr_head');
insert into cp select 'doc',(hr_career_documents((select v from cp where k='app'),'{"title":"Education certificate","message":"Upload the requested PDF certificate"}')->0->>'id')::uuid;
insert into cp select 'program',(hr_training_program_save(null,'Candidate induction test',null,current_date-2,null)->>'id')::uuid;
select test.must_fail($$select hr_career_training((select v from cp where k='app'),(select v from cp where k='program'),false)$$,'unverified documents block enrollment','Verify every requested');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.must_fail($$select career_documents((select v from cp where k='doc'),(select v from cp where k='file'))$$,'a submitted resume cannot be repurposed as a joining document','new PDF');
insert into cp select 'docfile',(career_file(null,'{"file_name":"certificate.pdf","size_bytes":10,"storage_provider":"SUPABASE"}')->>'id')::uuid;
reset role;
set role service_role;
select career_file_verified((select v from cp where k='docfile'),10,(select v::text from cp where k='one')||'/sealed/certificate.pdf');
reset role;
set role authenticated;
select career_documents((select v from cp where k='doc'),(select v from cp where k='docfile'));
select test.check(jsonb_array_length(career_file())=1,'joining document is excluded from resume picker');
select test.login('hr_head');
select hr_career_documents((select v from cp where k='app'),jsonb_build_object('id',(select v from cp where k='doc'),'version',2,'status','APPROVED','message','Verified'));
insert into cp select 'enrollment',(hr_career_training((select v from cp where k='app'),(select v from cp where k='program'),false)->>'enrollment_id')::uuid;
select hr_career_training((select v from cp where k='app'),(select v from cp where k='program'),false);
select test.must_fail($$select hr_career_training((select v from cp where k='app'),null,true)$$,'incomplete training cannot approve placement','Complete all training days');
select hr_training_day_save((select v from cp where k='program'),3,'Final assessment','["Practical evaluation"]','Trainer',null,'[{"name":"Practical","max":10}]',60);
select hr_training_report_save((select v from cp where k='enrollment'),1,'PRESENT','["Induction"]','[]','[]',null,null,null);
select hr_training_report_save((select v from cp where k='enrollment'),2,'PRESENT','["Practice"]','[]','[]',null,null,null);
select hr_training_report_save((select v from cp where k='enrollment'),3,'PRESENT','["Practical evaluation"]','[]','[{"criterion":"Practical","score":8}]',null,null,null);
select test.must_fail($$select hr_career_training((select v from cp where k='app'),null,true)$$,'trainer reports alone do not bypass the three online tests','all three training days');
reset role;
select test.check((select count(*)=1 from hr_training_enrollments where candidate_application_id=(select v from cp where k='app')),'training enrollment retry creates no duplicate');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select test.check(career_training()->0#>>'{days,2,assessment_result}'='PASS','candidate sees verified training evidence');
select test.must_fail($$select hr_career_training((select v from cp where k='app'),null,true)$$,'candidate cannot approve own placement','FORBIDDEN');
reset role;
select test.check(not exists(select 1 from profiles where id=(select v from cp where k='one')),'accepted offer and enrollment do not create staff access');
select test.check((select count(*)=count(distinct event_id) from career_mail_jobs),'candidate email jobs have unique event deduplication keys');
-- Native training MCQs do not replace trainer attendance/practical evidence.
set role authenticated;
do $$ declare d integer; tid uuid; aid uuid; result jsonb; begin
 for d in 1..3 loop
  perform set_config('request.jwt.claims',jsonb_build_object('sub',test.id('hr_head'),'role','authenticated')::text,true);
  select (x->>'id')::uuid into tid from jsonb_array_elements(hr_career_tests(jsonb_build_object('title','Training day '||d,'duration_minutes',10,'pass_percent',100,'questions','[{"prompt":"Confirm understanding","options":["Ready","Not yet"],"correct":0}]'::jsonb))) x where x->>'title'='Training day '||d;
  aid:=(hr_career_training_invite((select v from cp where k='app'),tid,now()+interval '1 day',d)->>'id')::uuid;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
  result:=career_assessment(aid,'{"action":"START"}');
  result:=career_assessment(aid,jsonb_build_object('action','SUBMIT','version',(result->>'version')::integer,'answers','{"0":0}'::jsonb));
  perform test.check((result->>'passed')::boolean,'training day '||d||' online test is server-graded');
 end loop;
end $$;
select test.login('hr_head');
select hr_career_training((select v from cp where k='app'),null,true);
select hr_career_training((select v from cp where k='app'),null,true);
reset role;
select test.check((select stage='COMPLETED' from career_applications where id=(select v from cp where k='app')),'verified training and all three online tests permit final HR placement');
select test.check(not exists(select 1 from profiles where id=(select v from cp where k='one')),'placement approval still requires separate staff activation');
-- Reapplying to a later hiring cycle retains identity; expiry never accepts late answers.
select test.login('hr_head');
set role authenticated;
select hr_career_posting(jsonb_build_object('position_id',(select id from hr_positions where title='Backend Developer'),'title','Portal next cycle','description','A new hiring cycle for the same engineering position.','location','Mumbai','employment_type','FULL_TIME','published',true));
reset role;
insert into cp select 'nextjob',id from career_postings where title='Portal next cycle';
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
insert into cp select 'nextapp',(career_apply((select v from cp where k='nextjob'),(select v from cp where k='file'))->>'id')::uuid;
select test.login('hr_head');
insert into cp select 'expiring',(hr_career_invite((select v from cp where k='nextapp'),(select v from cp where k='test'),now()+interval '1 day')->>'id')::uuid;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select v from cp where k='one'),'role','authenticated')::text,true);
set role authenticated;
select career_assessment((select v from cp where k='expiring'),'{"action":"START"}');
select career_assessment((select v from cp where k='expiring'),'{"action":"SAVE","version":2,"answers":{"0":0}}');
reset role;
update career_attempts set deadline=now()-interval '1 minute' where id=(select v from cp where k='expiring');
set role authenticated;
select test.check(career_assessment((select v from cp where k='expiring'),'{"action":"SUBMIT","version":3,"answers":{"0":1}}')->>'score'='0','late corrected answers are ignored after server deadline');
select career_withdraw((select v from cp where k='nextapp'));
select career_withdraw((select v from cp where k='nextapp'));
reset role;
select test.check((select stage='WITHDRAWN' from career_applications where id=(select v from cp where k='nextapp')),'withdrawal is durable and idempotent');
select test.check((select count(distinct hr_candidate_id)=1 from career_applications),'new hiring cycle reuses the previously verified internal HR link');
rollback;
